    panels = [
        [[grid[r][s + c] for c in range(5)] for r in range(1, 6)]
        for s in starts[:3]
    ]

    panel_bg = Counter(
        panels[p][r][c]
        for p in range(3)
        for r in range(5)
        for c in range(5)
    ).most_common(1)[0][0]

    # Axis indicated by the first panel's line.
    mask = [
        [1 if panels[0][r][c] != panel_bg else 0 for c in range(5)]
        for r in range(5)
    ]
    candidates = {
        "vertical": sum(mask[r][2] for r in range(5)),
        "horizontal": sum(mask[2][c] for c in range(5)),
        "diagonal": sum(mask[i][i] for i in range(5)),
        "anti": sum(mask[i][4 - i] for i in range(5)),
    }
    axis = max(candidates, key=candidates.get)

    def side(r, c):
        if axis == "vertical":
            return c - 2
        if axis == "horizontal":
            return r - 2
        if axis == "diagonal":
            return c - r
        return r + c - 4

    def reflect(r, c):
        if axis == "vertical":
            return r, 4 - c
        if axis == "horizontal":
            return 4 - r, c
        if axis == "diagonal":
            return c, r
        return 4 - c, 4 - r

    # A mark away from the axis indicates the side for panel 2.
    direction = 0
    for r in range(5):
        for c in range(5):
            if mask[r][c] and side(r, c) != 0:
                direction += side(r, c)
    if direction == 0:
        direction = -1

    # Fold panel 2 to the indicated side; fold panel 3 to the other side.
    for panel_index, target_sign in ((1, direction), (2, -direction)):
        color = next(
            panels[panel_index][r][c]
            for r in range(5) for c in range(5)
            if panels[panel_index][r][c] != panel_bg
        )
        for r in range(5):
            for c in range(5):
                if panels[panel_index][r][c] == color:
                    rr, cc = r, c
                    if side(r, c) * target_sign < 0:
                        rr, cc = reflect(r, c)
                    out[rr + 1][19 + cc] = color

    # Clear any untouched destination cells to the panel background.
    for r in range(5):
        for c in range(5):
            if out[r + 1][19 + c] == grid[0][0]:
                out[r + 1][19 + c] = panel_bg

    return out
