    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    starts = (1, 7, 13, 19)
    panels = [
        [[grid[r + 1][starts[p] + c] for c in range(5)] for r in range(5)]
        for p in range(3)
    ]

    fill = Counter(v for p in panels for row in p for v in row).most_common(1)[0][0]
    colors = [
        next(v for row in p for v in row if v != fill)
        for p in panels
    ]

    # In the first panel, the connected crease is the largest 8-connected
    # component; any separate colored cell indicates the fold direction.
    a = panels[0]
    crease_color = colors[0]
    marked = {(r, c) for r in range(5) for c in range(5)
              if a[r][c] == crease_color}

    components = []
    unseen = set(marked)
    while unseen:
        seed = unseen.pop()
        comp = {seed}
        q = [seed]
        while q:
            r, c = q.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in unseen:
                        unseen.remove(p)
                        comp.add(p)
                        q.append(p)
        components.append(comp)

    boundary = max(components, key=len)

    # Find the regions separated by the crease (using orthogonal adjacency).
    region = [[-1] * 5 for _ in range(5)]
    regions = []
    for r in range(5):
        for c in range(5):
            if (r, c) in boundary or region[r][c] != -1:
                continue
            rid = len(regions)
            cells = []
            region[r][c] = rid
            q = deque([(r, c)])
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < 5 and 0 <= nc < 5
                            and (nr, nc) not in boundary
                            and region[nr][nc] == -1):
                        region[nr][nc] = rid
                        q.append((nr, nc))
            regions.append(cells)

    # Choose which side receives panel 2 versus panel 3 by maximizing the
    # number of their colored cells retained. On a tie, use the separate
    # marker in panel 1 to choose panel 2's side.
    if len(regions) >= 2:
        def count_on(panel, rid):
            return sum(panel[r][c] == colors[panels.index(panel)]
                       for r, c in regions[rid])

        # Avoid relying on panel equality/lookup if panels happen to match.
        def marked_count(panel_index, rid):
            return sum(panels[panel_index][r][c] == colors[panel_index]
                       for r, c in regions[rid])

        s0 = marked_count(1, 0) + marked_count(2, 1)
        s1 = marked_count(1, 1) + marked_count(2, 0)

        if s0 > s1:
            bside = 0
        elif s1 > s0:
            bside = 1
        else:
            marker = marked - boundary
            marker_cell = next(iter(marker), None)
            marker_region = (region[marker_cell[0]][marker_cell[1]]
                             if marker_cell else 0)
            bside = marker_region if marker_region in (0, 1) else 0
    else:
        bside = 0

    for r in range(5):
        for c in range(5):
            b_on = panels[1][r][c] == colors[1]
            c_on = panels[2][r][c] == colors[2]

            if (r, c) in boundary:
