            elif len(regions) >= 2 and region[r][c] >= 0:
                rid = region[r][c]
                if rid == bside:
                    value = colors[1] if b_on else fill
                else:
                    value = colors[2] if c_on else fill
            else:
                value = fill

            out[r + 1][19 + c] = value

    return out
